  ui_story_5071_50710101_29_dialog_content = "แต่จงเปิดตาของคุณอยู่เสมอสำหรับสิ่งที่เงามืดของเรามองไม่เห็น",
  ui_story_5071_50710101_30_dialog_content = "แน่นอน ลูกสาวของฉัน ฉันเชื่อว่าคุณจะจัดการการประชุมกับ \"ลูกค้า\" ที่นั่นได้ดีเลยทีเดียว",
  ui_story_5071_50710101_31_dialog_content = "ฉันจะไม่ทำให้คุณผิดหวัง, พ่อ",
  ui_story_5071_50710101_32_dialog_content = "เบเธล ในฐานะหัวหน้ากิลด์ หน้าที่ของคุณคือต่ออัมบราตันเท่านั้น ไม่ใช่ต่อบุคคลอื่น",
  ui_story_5071_50710101_33_dialog_content = "ท่านพ่อ...",
  ui_story_5071_50710101_34_dialog_content = "เอาล่ะ ฉันควรจะไปแล้วนะ ฉันไปส่งคุณที่ประตูนะ",
  ui_story_5071_50710101_35_dialog_content = "...",
  ui_story_5071_50710101_36_dialog_content = "กิลด์ที่เกิดขึ้นจากเงามืดเพื่อบินอย่างอิสระบนท้องฟ้า...",
  ui_story_5071_50710101_37_dialog_content = "<color=#FFB400>ความฝันของคุณ</color>... มันเป็นจริงแล้วหรือยัง?",
  ui_story_5071_50710101_38_dialog_content = "<color=#e8d9bb>เปรี๊ยะ!</color>",
  ui_story_5071_50710101_39_dialog_content = "อย่าเพิกเฉยเลยนะ ฉันรับรู้กลิ่นของการนินทาในอากาศ!",
  ui_story_5071_50710101_40_dialog_content = "หืมม?",
  ui_story_5071_50710101_41_dialog_content = "สวัสดี ฉันชื่อ Brandy ฉันเป็นนักข่าวของ The Daily Scoop!",
  ui_story_5071_50710101_42_dialog_content = "ฉันขอถามความคิดเห็นของคุณเกี่ยวกับ<color=#FFB400>เรือเหาะ Cloudrover ขนาดใหญ่</color>ที่ถูกสร้างโดยกิลด์เหนือเมฆได้หรือไม่?",
  ui_story_5071_50710101_43_dialog_content = "ไม่มีความเห็น.",
  ui_story_5071_50710101_44_dialog_content = "นั่นเป็นการตีออกอย่างรวดเร็ว พวกเศรษฐีเหล่านี้แข็งเหมือนหอยนางรมที่ยากที่จะพรายเปิด.",
  ui_story_5071_50710101_45_dialog_content = "แต่ดูสิว่าใครมา—",
  ui_story_5071_50710101_46_dialog_content = "PlayerName! ทางนี้ ทางนี้!",
  ui_story_5071_50710101_47_dialog_content = "<color=#e8d9bb>เปรี๊ยะ!</color>",
  ui_story_5071_50710101_48_dialog_content = "คุณได้รับเชิญเข้าร่วม<color=#FFB400>การเปิดตัวครั้งแรก</color>ในวันนี้หรือไม่ PlayerName? มีความคิดเห็นอย่างไรเกี่ยวกับเรือเหาะบ้าง?",
  ui_story_5071_50710101_49_dialog_content = "รู้สึกคุ้นเคยนะ",
  ui_story_5071_50710101_50_dialog_content = "แม้ว่าเทคโนโลยีที่ใช้ในเรือเหาะนี้จะต่างจากโคลอสซัส แต่มันก็ยังคงเป็นเรือที่มีขนาดใหญ่และสามารถบินได้",
  ui_story_5071_50710101_51_dialog_content = "รู้สึกว่าน่าประทับใจ",
  ui_story_5071_50710101_52_dialog_content = "ฉันเคยเห็นเรือเหาะขนาดเล็ก ๆ ก่อนหน้านี้เท่านั้น ฉันไม่รู้เลยว่าท่านหญิงเชโอลได้สร้างเรือเหาะขนาดใหญ่พอที่จะพากิลด์ของเธอทั้งหมดขึ้นไป...",
  ui_story_5071_50710101_53_dialog_content = "เรือเหาะ Cloudrover นี้เป็นยอดของเรือเหาะทั้งหมด แต่ไม่ใหญ่เท่ากับ Soroz ของคุณใช่ไหม, PlayerName?",
  ui_story_5071_50710101_54_dialog_content = "ไม่ แต่... ในเรื่องขนาด มันคงจะใหญ่เท่ากับ Eulogoz ที่พวกเขาเคยจัดคอนเสิร์ตไว้ก่อนหน้านี้",
  ui_story_5071_50710101_55_dialog_content = "อ๋า, ฉันเห็นพาดหัวข่าวของวันพรุ่งนี้แล้วครับ!",
  ui_story_5071_50710101_56_dialog_content = "\"Caelestite ประกาศ: เรือบิน Cloudrover ไม่สามารถเทียบเท่ากับ Soroz!\"",
  ui_story_5071_50710101_57_dialog_content = "ด-เดี๋ยว ทำไมคุณถึงบิดเบือนคำพูดของฉันแบบนั้น?",
  ui_story_5071_50710101_58_dialog_content = "<color=#e8d9bb>ซ่า—ซ่า—</color>",
  ui_story_5071_50710101_59_dialog_content = "อย่ากลัวอันตรายหรือความล้มเหลว ความเพียรจะเปลี่ยนเป็นโชคชะตา!",
  ui_story_5071_50710101_60_dialog_content = "หายไปนานเลยนะเพื่อนรักของฉัน! คุณทั้งหมดเป็นอย่างไรบ้าง?",
  ui_story_5071_50710101_61_dialog_content = "นั่นไม่ใช่... โกลดี, ไอดอลที่กำลังเป็นที่นิยมอย่างมากใน Umbraton ในขณะนี้หรือไม่? ถ้ากิลด์เหนือเมฆสามารถทำให้เธอเข้าร่วม นั่นก็ยอดเยี่ยมเหมือนที่เคยเสมอ!",
  ui_story_5071_50710101_62_dialog_content = "คุณไม่รู้หรอ? ท่านหญิงเชโอล ผู้นำของกิลด์เหนือเมฆ คือคนที่ทำให้เธอมีชื่อเสียง!",
  ui_story_5071_50710101_63_dialog_content = "กิลด์เหนือเมฆยังได้แทรกแซงเข้าไปในอุตสาหกรรมบันเทิงด้วยหรือ? ท่านหญิงเชโอลเข้าไปมีส่วนในอุตสาหกรรมอะไรบ้างนะ?",
  ui_story_5071_50710101_64_dialog_content = "ใครจะแคร์ไอดอลหรือเรือเหาะล่ะ? ทั้งหมดนั้นแค่เพียงของเล่น... สาเหตุที่ฉันอยู่ที่นี่เพราะเจ้าแห่งเงากำลังเข้าร่วมเท่านั้นเอง.",
  ui_story_5071_50710101_65_dialog_content = "ใจเย็นๆ นะทุกคน พิธีจะเริ่มแล้วนะ!",
  ui_story_5071_50710101_66_dialog_content = "จนกระทั่งเวลานั้น ฉันอยากจะแสดงซิงเกิลใหม่ให้คุณฟัง—",
  ui_story_5071_50710101_67_dialog_content = "<size=45>ฝันที่อยู่ในระยะทางที่สามารถเข้าถึง!</size>",
  ui_story_5071_50710101_68_dialog_content = "กรุณามุ่งมั่นที่จะขี่ลมและสัมผัสท้องฟ้าในไม่ช้านี้กับฉันนะ!",
  ui_story_5071_50710101_69_dialog_content = "♪ ในท้องฟ้าที่ไม่มีขอบเขต กลุ่มเมฆเป็นสัญญาณแห่งความหวัง ในขณะที่ฝันขึ้นสู่ขอบฟ้าเหมือนดวงอาทิตย์ในเช้าวัน ♪",
  ui_story_5071_50710101_70_dialog_content = "♪ กางปีกของคุณ ซิ่งเหินเวหา และสัมผัสกับแสงสว่างอันสุดยอด ♪",
  ui_story_5071_50710101_71_dialog_content = "(นั่นแหละ โกลดี้ สำหรับคุณ หรือไม่? ทั้งหมดที่เธอต้องการคือการร้องเพลงเพื่อให้ผู้โดยสารที่โกรธทั้งหมดสงบลง พวกเขายังมีการสั่นหัวตามจังหวะของเพลงของเธออีกด้วยนะ)",
  ui_story_5071_50710101_72_dialog_content = "(แต่ก็ยัง... ถ้าโกลดี้อยู่ที่นี่ แล้วแฟนคลับที่กรีดร้องของเธอก็ควรจะอยู่ที่นี่เพื่อทำให้หูฉันแตกตาม, ใช่ไหม?)",
  ui_story_5071_50710101_73_dialog_content = "(ฉันไม่รู้จักใครเลยที่ท่านหญิงเชโอลเชิญขึ้นเรือเหาะ...)",
  ui_story_5071_50710101_74_dialog_content = "เขามาแล้ว! เขามาแล้ว! ท่านเจ้าแห่งเงามาแล้ว! ไปทางนั้นกัน—",
  ui_story_5071_50710101_75_dialog_content = "(ท่านเจ้าแห่งเงาก็มาด้วยเหรอ? นี่ต้องเป็นงานพิเศษแน่นอน...)",
  ui_story_5071_50710101_76_dialog_content = "มาตรงเวลาเหมือนเคยเลยนะ เจ้าแห่งเงา อีกหนึ่งนาทีคุณก็จะพลาดการตัดสายริบบิ้นแล้ว",
  ui_story_5071_50710101_77_dialog_content = "การเข้าร่วมงานในเวลาที่เหมาะสมเหมือนกับนี้เป็นความลับที่ฉันได้เรียนรู้จากคุณ Lady Sheol.",
  ui_story_5071_50710101_78_dialog_content = "เจ้าแห่งเงาครับ! ฉันยินดีมากที่ได้เจอคุณในโอกาสดีๆ นี้!",
  ui_story_5071_50710101_79_dialog_content = "เจ้าแห่งเงาที่รักของฉัน, คุณยังจำฉันได้เหรอ?",
  ui_story_5071_50710101_80_dialog_content = "เจ้าแห่งเงา ฉันได้ขอพบคุณเป็นส่วนตัวเมื่อสักครู่ คุณได้อ่านคำเชิญของฉันหรือยัง?",
  ui_story_5071_50710101_81_dialog_content = "เจ้าแห่งเงาครับ! อย่าลืมฉันนะ! เจ้าแห่งเงา—",
  ui_story_5071_50710101_82_dialog_content = "สุภาพสตรีและสุภาพบุรุษทุกท่าน เจ้าแห่งเงาได้รับมอบหมายให้พบกับทุกคนของคุณบนเรือเหาะในวันนี้",
  ui_story_5071_50710101_83_dialog_content = "แน่นอน แค่ผู้ที่ได้ร้องขอเข้าเฝ้ากับเขาล่วงหน้าเท่านั้นที่จะได้รับเกียรติแบบนี้",
  ui_story_5071_50710101_84_dialog_content = "แต่ในขณะนี้ ขอให้เราทุกคนเอาสายตาไปที่นักร้องสาวที่ยอดเยี่ยมของเราและการแสดงที่มีชีวิตชีวาของเธอค่ะ",
  ui_story_5071_50710101_85_dialog_content = "ตรงจริงๆ ฉันไม่เคยรู้ว่าการพบกับเจ้าแห่งเงาจำเป็นต้องมีกฎระเบียบเยอะแยะเท่านี้",
  ui_story_5071_50710101_86_dialog_content = "...",
  ui_story_5071_50710101_87_dialog_content = "ขออภัยด้วยนะครับ ผมยังไม่ได้มีโอกาสแนะนำตัวเองอย่างเป็นทางการ ผมชื่อฮันส์ตี้ ผู้นำของกิลด์คอนติเนนทัล นี่เป็นครั้งแรกที่ผมมาที่นี่ และผมยังไม่คุ้นเคยกับการทำงานของอัมบราตัน หากผมทำให้ใครสักคนรบกวนความสนุกสนานของงานเทศกาล ขออภัยด้วยครับ",
  ui_story_5071_50710101_88_dialog_content = "ดูสิ... นั่นไม่ใช่นางฮันสตีจากกิลด์ทวีปหรือเปล่า? ฉันได้ยินว่าเธอไม่เคยปรากฏตัวในที่ใดเลย! ท่านหญิงเชโอลนี่มีเสน่ห์จริง ๆ ... หรือนี่คือเสน่ห์ของ Shadowlord?",
  ui_story_5071_50710101_89_dialog_content = "กิลด์ทวีป? มีกิลด์แบบนี้อยู่ในอัมบราตันเหรอ?",
  ui_story_5071_50710101_90_dialog_content = "กิลด์คอนติเนนทัลได้เริ่มดำเนินธุรกิจในเมืองเล็กๆ นอกอัมบราตันในปีหลังๆ นี้ แม้ว่ามันเพิ่งจะสร้างฐานที่อัมบราตัน แต่ความเร็วในการพัฒนาของมันไม่ควรถูกมองข้าม!",
  ui_story_5071_50710101_91_dialog_content = "เป็นเกียรติอย่างยิ่งที่มีคุณอยู่ที่นี่ คุณฮันสตี้",
  ui_story_5071_50710101_92_dialog_content = "กิลด์ Cloudrover ได้เชิญหัวหน้ากิลด์ที่มีชื่อเสียงทุกคนใน Umbraton เข้าร่วมงานนี้ ฉันจะพลาดโอกาสดี ๆ แบบนี้ได้อย่างไร?",
  ui_story_5071_50710101_93_dialog_content = "และที่สำคัญ เมื่อฉันได้ยินว่าเจ้าแห่งเงาที่มีชื่อเสียงกำลังจะมาปรากฏตัว ฉันก็รู้ว่าฉันต้องอยู่ที่นี่",
  ui_story_5071_50710101_94_dialog_content = "อ๊ะ คุณต้องเป็นท่านหญิงเชโอล ผู้นำของ <color=#FFB400>กิลด์เหนือเมฆ</color> และเป็นบุคคลที่ฉันต้องยกมองเท่านั้น",
  ui_story_5071_50710101_95_dialog_content = "คุณล้อเล่นนะคะ คุณฮันสตี้",
  ui_story_5071_50710101_96_dialog_content = "เครือข่ายของ<color=#FFB400>กิลด์ทวีป</color>สะท้อนถึงทั่วทั้งแอสตรา ท้องฟ้าและแผ่นดินสามารถและทำการอยู่ร่วมกันได้",
