  ui_story_5071_50710101_107_dialog_content = "(เดี๋ยว, เจ้าแห่งเงากำลังฝ่าฝืนกฎของตัวเองเพื่อผู้หญิงที่สวยงามและโอ้อวดนั้นเหรอ?)",
  ui_story_5071_50710101_108_dialog_content = "คุณจะยืนอึ้งในมุมนั้นอีกนานแค่ไหนเนี่ย PlayerName?",
  ui_story_5071_50710101_109_dialog_content = "G-สวัสดีครับ, เจ้าแห่งเงา! ทุกคนยุ่งมากจนฉันไม่มีโอกาสที่จะทักทายท่านเร็วกว่านี้.",
