  ui_story_5071_50710101_112_dialog_content = "ฉันหวังว่าทุกคนต้องรักเพลงนั้น! ต่อไป เราขอต้อนรับ—",
  ui_story_5071_50710101_113_dialog_content = "เจ้าแห่งเงาอีสต์วาน, ท่านหญิงเชโอลผู้นำกิลด์เหนือเมฆ, และPlayerName, แขกรับเชิญพิเศษของอัสตรา, ที่จะมาตัดสายริบบอนด้วยกัน!",
