  ui_story_5071_50710201_8_dialog_content = "ข้าพเจ้า... พูดอะไรกันนั่นนะ... เจ้าแห่งเงา โปรดอภัยให้ข้าพเจ้าที่พูดเรื่องไร้สาระนี้",
  ui_story_5071_50710201_9_dialog_content = "มันเป็นเรื่องปกติที่จะกังวลเรื่องนั้น ลูกชายของคุณมีความสามารถมาก...",
  ui_story_5071_50710201_10_dialog_content = "ฉันหวังว่าเขาจะกลับมาอย่างปลอดภัยและก่อตั้งโรงเรียน Umbraton มากกว่าใคร",
