  ui_story_5071_50710201_16_dialog_content = "ขอบคุณสำหรับการสนับสนุนอย่างต่อเนื่องของคุณ, PlayerName!",
  ui_story_5071_50710201_17_dialog_content = "ฉันจะไม่ทำให้คุณผิดหวัง และฉันจะทำดนตรีที่ดีต่อไป!",
  ui_story_5071_50710201_18_dialog_content = "ไม่ต้องพูดถึงมัน! คุณมีความสัมพันธ์พิเศษกับท้องฟ้าจริง ๆ ใช่ไหม? เพลงของวันนี้ก็เช่นกัน—",
