  ui_story_5071_50710201_20_dialog_content = "ขอโทษนะ PlayerName อย่าลืมมาหาฉันที่สำนักงานเมื่อคุณมีเวลานะ!",
  ui_story_5071_50710201_21_dialog_content = "โกลดี้! โกลดี้! เราก็ต้องการคุยกับคุณนานขึ้นหน่อย!",
  ui_story_5071_50710201_22_dialog_content = "ภายในไม่กี่เวลา โกลดี้ได้ทำให้คนจำนวนมากกลายเป็นแฟนของเธอ...",
