  ui_story_5071_50710201_27_dialog_content = "ป-ปราณี... แต่ฉันต้องการความช่วยเหลือจากคุณตอนนี้มากกว่าเดิม!",
  ui_story_5071_50710201_28_dialog_content = "ขอบคุณคุณที่ทำให้ฉันสามารถเปิดร้านค้าทั่วไปได้หลายแห่ง ธุรกิจของฉันอาจจะไม่เทียบเท่ากับกิลด์เหนือเมฆ แต่ก็ทำได้ดีพอที่นี่",
  ui_story_5071_50710201_29_dialog_content = "โชคร้าย ร้านค้าใกล้เคียงกำลังร่วมมือกันเพื่อให้ฉันต้องปิดกิจการเมื่อเร็ว ๆ นี้ ฉันกำลังอยู่ในช่วงของการล้มละลายแล้ว...",
  ui_story_5071_50710201_30_dialog_content = "ฉันไม่รู้ว่าฉันควรทำอะไรอีก นายท่าน... ช่วยฉันด้วย...",
  ui_story_5071_50710201_31_dialog_content = "คุณต้องการให้ฉันช่วยคุณกำจัดพวกมันใช่ไหม?",
  ui_story_5071_50710201_32_dialog_content = "ว-ว่างั้นจะเป็นไรไหม?",
  ui_story_5071_50710201_33_dialog_content = "ทำไมไม่เข้าร่วมกิลด์เลยล่ะ? ถ้าคุณดำเนินการตามข้อบังคับ พวกเขาจะให้คุ้มครองที่มีนัยสำคัญกับคุณ",
  ui_story_5071_50710201_34_dialog_content = "ฉัน... ฉันได้ยินว่าการเข้าร่วมกิลด์ต้องจ่ายค่าสมาชิกที่สูงมาก...",
  ui_story_5071_50710201_35_dialog_content = "คุณจะรู้ได้อย่างไรถ้าคุณไม่เคยเดินผ่านประตูของพวกเขาเพื่อหาความจริง?",
  ui_story_5071_50710201_36_dialog_content = "ว่าแล้วเชียว! พวกเจ้านั่นกล่าวโกหกฉันมาตลอดเวลา!",
  ui_story_5071_50710201_37_dialog_content = "งั้น... ฉันสามารถเข้าร่วมกิลด์ของคุณได้ไหม?",
  ui_story_5071_50710201_38_dialog_content = "ฉันไม่ใช่หัวหน้ากิลด์ แต่ฉันสามารถบอกคุณได้ว่าประตูของกิลด์เราเปิดต้อนรับทุกคนเสมอ",
  ui_story_5071_50710201_39_dialog_content = "เชื่อฉันนะ คุณจะเสียใจที่ไม่ได้ทำมันเร็วกว่านี้",
  ui_story_5071_50710201_40_dialog_content = "โอ้ ขอบคุณครับ! ขอบคุณมากเลยครับ เจ้าแห่งเงา! ตั้งแต่นี้ไป ผมจะสาบานว่าจะสนับสนุนคุณ... และการตัดสินใจของกิลด์ด้วยครับ!",
  ui_story_5071_50710201_41_dialog_content = "คนที่ฝังพ่อแม่ของคุณน่าจะได้ออกจากโลกนี้ไปนานแล้ว ดูเหมือนว่าผู้ชายคนนั้นและฉันมี \"งานอดิเรก\" ที่คล้ายคลึงกัน",
  ui_story_5071_50710201_42_dialog_content = "นั่นไม่ใช่ประเด็น คุณเคลเคน บอกเขาว่าควรทำอะไรต่อไป",
  ui_story_5071_50710201_43_dialog_content = "ดีมาก ชาโดว์ลอร์ด",
  ui_story_5071_50710201_44_dialog_content = "<color=#e8d9bb>ด้านนอกโรงภาพยนตร์ของเรือเหาะเหนือเมฆ</color>",
  ui_story_5071_50710201_45_dialog_content = "\"เอาเลย, 'เรื่องราววัยรุ่นจากเรื่องจริง, 'ตามล่า Alleywood' กำลังฉายอยู่ มีตั๋วเหลืออีกหนึ่งใบเท่านั้น\"",
  ui_story_5071_50710201_46_dialog_content = "นี่คือผลงานล่าสุดของลิลิก้าหรือไม่? นี่อาจจะอธิบายได้ว่าทำไมฉันไม่ได้ยินจากเธอมานานแค่ไหน...",
  ui_story_5071_50710201_47_dialog_content = "เอาล่ะ ฉันไม่มีอะไรที่ดีกว่านี้ที่จะทำ ดังนั้นฉันอาจจะแสดงการสนับสนุนบ้าง!",
  ui_story_5071_50710201_48_dialog_content = "รบกวนหน่อยค่ะ ฉันอยากซื้อตั๋วรอบสุดท้ายของ \"Chasing Alleywood\" ค่ะ!",
  ui_story_5071_50710201_49_dialog_content = "อืมม? บรั่นดีเอาตั๋วสุดท้ายไปเอง!",
  ui_story_5071_50710201_50_dialog_content = "เกิดอะไรขึ้นกับเด็กคนนี้น่ะ? ทำไมเขาถึงไม่พูดล่ะ?",
  ui_story_5071_50710201_51_dialog_content = "เขาหลงทางหรือเปล่า? ทำไมพ่อแม่ของเขาไม่มาหาเขาเนี่ย?",
