  ui_story_5071_50710201_68_dialog_content = "ฮ่าฮ่า ถ้าฉันไม่ได้มา ฉันกลัวว่ากลุ่มหนึ่ง ๆ และสิ่งที่พวกเขาเรียกว่า \"การปฏิรูป\" คงจะปล้นทรัพย์สินทั้งหมดของฉันที่อัมบราตันไปแล้ว",
