  ui_story_5071_50710402_88_dialog_content = "นี่คือประเภทของกระดาษเขียนที่ทุกคนใช้ในปัจจุบัน—",
  ui_story_5071_50710402_89_dialog_content = "ฮะ? รอสักครู่! นี่มัน...",
  ui_story_5071_50710501_1_dialog_content = "แน่ใจนะว่านี่คือต้นฉบับของคุณอีวอน?",
  ui_story_5071_50710501_2_dialog_content = "มันคือ! ตามที่ฉันทราบ นี่เป็นเรื่องใหม่ที่ไม่เคยถูกเผยแพร่มาก่อน!",
  ui_story_5071_50710501_3_dialog_content = "แต่หน้าเหล่านี้ดูเก่ามาก ทำไมยังไม่ได้ตีพิมพ์ลงหนังสือเล่มนี้?",
  ui_story_5071_50710501_4_dialog_content = "มีเหตุผลมากมายที่ทำให้นักเขียนไม่สามารถเผยแพร่งานของพวกเขาได้ตรงเวลา นอกจากนี้ ลองดูหน้าสุดท้ายของต้นฉบับนี้: พวกเขายังค่อนข้างใหม่!",
  ui_story_5071_50710501_5_dialog_content = "นี่อาจจะเป็นต้นฉบับที่สูญหายของเรื่องใหม่ของนาง Yvonne! อ๊าก, ฉันรออ่านมันไม่ไหวแล้ว...",
  ui_story_5071_50710501_6_dialog_content = "คุณไม่คิดว่าเราควรคืนมันให้กับเจ้าของที่ถูกต้องก่อนหรือไม่ วีร์จิล?",
  ui_story_5071_50710501_7_dialog_content = "อ๊ะ, แค่บรรทัดแรกของต้นฉบับนี้ก็เพียงพอที่จะทำให้น้ำตาฉันไหล! ครั้งสุดท้ายที่ฉันอ่านผลงานของนาง Yvonne, ฉันยังสูงไม่เกินเก้าอี้จาก Longzhou โบราณ!",
