  ui_story_5071_50710501_16_dialog_content = "พวกเขามัดคนร้ายทุกประเภทด้วยโซ่เหล็กหนาเท่าชามเหมือนสัตว์ แล้วทอดพวกเขาลงไปในเดอะพิตเพื่อต่อสู้",
