  ui_story_5071_50710601_13_dialog_content = "แต่คุณแน่นอนไม่ได้ทำกับฉันเหมือนเพื่อนเก่า ฉันมาเยี่ยมคุณด้วยความตั้งใจดี แต่คุณกลับพยายามทำให้ฉันตกต่ำลง",
  ui_story_5071_50710601_14_dialog_content = "เราเป็นเพื่อนเก่ากัน, นั่นเป็นเหตุผลว่าทำไมฉันถึงต้องการสิ่งที่ดีที่สุดให้กับคุณ",
  ui_story_5071_50710601_15_dialog_content = "ฉันไม่ค่อยเข้าใจนะ แต่<color=#FFB400>อัมบราตันของคุณ</color> ไม่ใช่เมืองที่เสรีและเปิดกว้างหรือเปล่า?",
  ui_story_5071_50710601_16_dialog_content = "คุณสามารถนำคาสิโนขนาดใหญ่เข้ามาเพื่อสร้างกำไรมากขึ้นให้กับ Umbraton และยังสามารถจ่าย \"ภาษีที่ดิน\" ขนาดใหญ่ให้กับ Lumopolis ได้ง่ายๆ ดังนั้นทำไมคุณไม่ทำล่ะ?",
  ui_story_5071_50710601_17_dialog_content = "คุณไม่ได้เริ่มต้นด้วยการสักการะเงิน ในอดีต คุณชื่นชอบศิลปะและวรรณกรรม มักมีปากกาหรือพู่กันอยู่ในมือเสมอ—",
