  ui_story_5071_50710601_20_dialog_content = "...",
  ui_story_5071_50710601_21_dialog_content = "คุณพูดถูก ไม่มีอะไรที่ยืนยงตลอดไป อัมบราตันกำลังปฏิรูปตัวเองในตอนนี้",
