  ui_story_5071_50710601_57_dialog_content = "ฉันหวังในสิ่งเดียวกัน แต่การปลดปล่อยตัวเราเองจากความมืดมนของอดีตไม่ใช่สิ่งที่ทำได้ในหนึ่งคืน...",
