  ui_story_5071_50711001_15_dialog_content = "ฉันควรทำต่อไปเพื่อความจริงหรือไม่? หรือฉันควรเก็บเรื่องราวเหล่านี้ซ่อนอยู่ลึก ๆ ในหัวใจของฉัน?",
  ui_story_5071_50711001_16_dialog_content = "ฉันมักจะมองเห็นเหตุการณ์ที่ชั่วร้ายเกิดขึ้นต่อหน้าฉัน ทำให้จิตสำนึกของฉันเสื่อมสึก ในตอนแรก ฉันคิดว่าฉันได้ชินกับมันแล้ว",
  ui_story_5071_50711001_17_dialog_content = "ถ้าฉันไม่ได้ค้นพบความจริงเกี่ยวกับความทะเยอทะยานล่าสุดของเขา ฉันอาจจะยังคงมองดูจากระยะไกล—",
  ui_story_5071_50711001_18_dialog_content = "ผ่านโอกาสที่บังเอิญ ฉันได้รู้ถึงความโลภที่ไม่มีที่สิ้นสุดของอีสต์วานจากผู้ใต้บังคับบัญชาของเขา ถึงแม้ว่าเขาจะนั่งอยู่ที่ยอดสุดของที่นั่ง แต่เขายังคงต้องการมากขึ้น",
  ui_story_5071_50711001_19_dialog_content = "แม้ว่าเขาจะแสดงตัวเป็นผู้ปกครองที่ใจกว้าง แต่ในความลับเขาไม่พอใจกับแก๊งและกิลด์ที่เป็นกลาง",
  ui_story_5071_50711001_20_dialog_content = "ผู้ที่ดำเนินการนอกเหนือจากการควบคุมของกิลด์ของเขาได้ทำให้เขารู้สึกว้าวุ่น... เขาจะไม่ยอมทนต่อการกบฏใด ๆ",
  ui_story_5071_50711001_21_dialog_content = "ด้วยเหตุผลนี้ เขาวางแผนที่จะใช้กิลด์ Cloudrover เพื่อรวบรวมฝ่ายตรงข้ามที่อาจจะเกิดขึ้น และทำลายพวกเขาครั้งสุดท้าย โดยการกระทำนี้ เขาจะได้รับสิ่งที่เขามักจะแสวงหา - การควบคุมอัมบราตันอย่างสิ้นเชิง",
  ui_story_5071_50711001_22_dialog_content = "ด้วยเวลาที่เหลือน้อยในโลกนี้ ฉันปรารถนาที่จะลงโทษให้กับผู้ชายที่อดีตของเขาถูกลืมเลือน",
  ui_story_5071_50711001_23_dialog_content = "—ลงชื่อ, อีวอน.",
  ui_story_5071_50711001_24_dialog_content = "เป็นเรื่องจริงเหรอครับ?",
  ui_story_5071_50711001_25_dialog_content = "นางอีวอนและเจ้าแห่งเงาเพิ่งมีการประชุมกันใช่ไหม?",
