  ui_story_5071_50711201_68_dialog_content = "หนอย...!",
  ui_story_5071_50711201_69_dialog_content = "<color=#e8d9bb>เอี๊ยด—</color>",
  ui_story_5071_50711201_70_dialog_content = "(ไม่น่าเชื่อ! เจ้าแห่งเงากำลังรับน้ำหนักของปีกทั้งหมดไว้ในทางหนึ่ง...)",
