  ui_story_5071_50711201_82_dialog_content = "(ด้วยอัตรานี้ เราจะไม่สามารถเปลี่ยนทิศทางได้เต็มที่ก่อนที่จะชน!)",
  ui_story_5071_50711201_83_dialog_content = "ไม่เพียงพอ มันจะยังคงตกอยู่ขอบเขตของอัมบราตัน...",
