  ui_story_5071_50711201_87_dialog_content = "ฟ-พลุ?",
  ui_story_5071_50711201_88_dialog_content = "ใครเนี่ยที่กำลังจุดพลุดอกไม้ไฟบนเรือเหาะตอนนี้...",
