  ui_story_5071_50711201_90_dialog_content = "เรือเหาะของกิลด์เหนือเมฆกำลังบินมาทางนี้!",
  ui_story_5071_50711201_91_dialog_content = "นี่เป็นหนึ่งในการฉลองสำหรับ Maiden Flight... ฉันแค่ไม่คาดคิดว่ามันจะใกล้เราขนาดนี้!",
  ui_story_5071_50711201_92_dialog_content = "พลุที่น่าตื่นตาตื่นใจมาก! เรือเหาะนั้นก็สวยงามไม่แพ้กันเลย",
  ui_story_5071_50711201_93_dialog_content = "Lady Sheol ต้องการให้เราสนุกกับงานนี้ด้วยแน่นอน!",
  ui_story_5071_50711201_94_dialog_content = "เฮ้ พวกเจ้าโง่! ทำไมถึงยืนอยู่เฉยๆ ล่ะ?",
  ui_story_5071_50711201_95_dialog_content = "รีบออกจากที่นี่! เรือเหาะกำลังจะตกแล้ว!",
  ui_story_5071_50711201_96_dialog_content = "ทำไมแก๊งอีสต์วานถึงน่ากลัวขนาดนี้?",
  ui_story_5071_50711201_97_dialog_content = "วิ่ง! ฉันได้ยินว่าเจ้าแห่งเงาได้เริ่มการสังหารทั่วไปและกำจัดทุกคนบนเรือเหาะ!",
  ui_story_5071_50711201_98_dialog_content = "พวกเขาต้องการที่จะชนเรือเหาะ Cloudrover ลงในสลัมของเรา!",
  ui_story_5071_50711201_99_dialog_content = "ตามเรามา! เราต้องหาที่หลบนอกเมือง—",
