  ui_story_5071_50711201_101_dialog_content = "ถ้าคุณเข้ามาใกล้กว่านี้ เราจะเริ่มโจมตีนะ!",
  ui_story_5071_50711201_102_dialog_content = "ทำไมคุณถึงคิดมากเกินไปกับเราล่ะ? เฮ้, หยุดขว้างก้อนหินใส่ผู้คนเถอะ!",
