  ui_story_5071_50711302_119_dialog_content = "ฉันนึกว่าฉันดูไม่น่าพอใจ ดังนั้นฉันดูเหมือนบาร์บาริคหรือเปล่า?",
  ui_story_5071_50711302_120_dialog_content = "(สีหน้าน่ากลัวมาก... แม้แต่เส้นเลือดของเขายังเห็นได้ชัดเจน เขาไม่เหมือนเจ้าแห่งเงาที่เคยเห็น...)",
