  ui_story_5071_50711401_7_dialog_content = "เขาไม่ได้ยินฉัน... ถ้าฉันติดต่อเขาไม่ได้แบบนี้ ฉันก็ไม่มีทางเลือกนอกจากการหาช่องทางในอารมณ์ของเขา",
  ui_story_5071_50711401_8_dialog_content = "แต่เขาหายไปไหน...",
  ui_story_5071_50711401_9_dialog_content = "ที่นี่... มันเป็นสนามประลองหรืออะไรเช่นนั้นหรือ?",
