  ui_story_5071_50711401_11_dialog_content = "ฉันก็ตกใจมากเหมือนกัน... คุณจำได้ไหมว่าครั้งสุดท้ายที่มีบอสมากมายรวมตัวกันเป็นเมื่อไหร่?",
  ui_story_5071_50711401_12_dialog_content = "เอา... เอาจริงๆ ทุกคนที่นี่เป็นสมาชิกแก๊งหรือ?",
