  ui_story_5071_50711401_20_dialog_content = "คุณอยากท้าฉันสู้ในหลุมหรือไม่?",
  ui_story_5071_50711401_21_dialog_content = "ฉันไม่เห็นด้วยกับพวกที่มาจากลูโมโพลิสที่เดินเข้ามาในอาณาเขตของเราอย่างนี้! พวกเขาไม่ได้ทิ้งอัมบราตันไปแล้วหรือเพราะกลัวกองทัพอิคลิพไซท์? ทำไมพวกเขาถึงกลับมา?",
  ui_story_5071_50711401_22_dialog_content = "เราได้ส่งพวกเขาออกไปแล้วครั้งหนึ่ง และตอนนี้พวกเขาต้องการที่จะวางกองกำลังของพวกเขาที่นี่หรือ? นั่นยุติธรรมหรือไม่?",
  ui_story_5071_50711401_23_dialog_content = "เราหยุดทะเลาะกันเถอะ! ถ้าถามฉัน ฉันคิดว่าเราควรร่วมมือกันเพื่อทำเงินจากเรื่องนี้! คนจนๆ ในเมืองนั้นไม่เกี่ยวข้องกับเราเลย ดังนั้นเราควรหมั่นเพียบเงินจากพวกเขาและใช้เงินนั้นเพื่อสร้างความประทับใจกับพวกจากลูโมโพลิส!",
  ui_story_5071_50711401_24_dialog_content = "คุณพูดถูก แต่เราอยู่ที่นี่ทั้งหมด เราควรจะปล้นกิลด์เหล่านั้น—",
  ui_story_5071_50711401_25_dialog_content = "ผู้สนับสนุนของฉันอยู่ในหมู่พวกเขา!",
  ui_story_5071_50711401_26_dialog_content = "นี่คือเดอะพิต ฉันเสนอว่าเราควรใช้กฎที่เก่าที่สุดเพื่อตัดสินว่าใครจะได้คทา",
  ui_story_5071_50711401_27_dialog_content = "เราไม่สามารถร่วมมือกันได้หรือ? เรายังไม่รู้ว่าจะมีคนเท่าไหร่ที่จะคุ้มครองพนักงาน",
  ui_story_5071_50711401_28_dialog_content = "ผู้ที่อยู่รอดจนถึงท้ายสุดสามารถนำทหารของเราไปยึดมันได้ มันง่ายเพียงเท่านี้",
  ui_story_5071_50711401_29_dialog_content = "ในสายตาของคุณ ลูกจ้างคนนั้นสำคัญกว่าอัมบราตันหรือ?",
  ui_story_5071_50711401_30_dialog_content = "แน่นอน! ไม้เท้าผู้นำฝูงแกะนั้นแทนถึงวงศ์ของอีสต์วานเก่าและยังกลายเป็นสัญลักษณ์ของสมาคมกิลด์...",
  ui_story_5071_50711401_31_dialog_content = "<size=45>พอแล้ว!</size>",
  ui_story_5071_50711401_32_dialog_content = "สิ่งสำคัญที่สุดในตอนนี้คือที่อยู่ของเด็กเวรนั่นคาเดและพนักงาน ทำไมเขาถึงใช้เวลานานขนาดนี้?",
  ui_story_5071_50711401_33_dialog_content = "คนเหล่านี้คือผู้ควบคุมอัมบราตันในอดีตหรือไม่? ที่นี่เป็นสถานที่แย่มาก...",
  ui_story_5071_50711401_34_dialog_content = "ฉันต้องใช้พลังของฉันเพื่อค้นหาเจ้าแห่งเงา และต้องรีบ...",
  ui_story_5071_50711401_35_dialog_content = "ฉันได้ยินว่าลูกชายของอีสต์วานคนแก่ วาลอน ทำงานได้ดีมากและกำลังบริหารกิลด์หลายแห่งอยู่แล้ว",
  ui_story_5071_50711401_36_dialog_content = "เขายังให้ประโยชน์มากมายกับเรา ฉันสงสัยว่าเขาคิดอย่างไรเกี่ยวกับการโจมตีของอิคลิพไซท์นี้",
  ui_story_5071_50711401_37_dialog_content = "ที่นั่น! รุ่นเยาว์ของท่านเจ้าแห่งเงากำลังซ่อนอยู่ในมุมนั้น—",
