  ui_story_5071_50711401_X41_dialog_content = "วาลอน? ทำไมในความทรงจำของเจ้าแห่งเงาจึงมีแค่ความทรงจำเบาๆเกี่ยวกับวาลอนเท่านั้น?",
  ui_story_5071_50711401_42_dialog_content = "เจ้าเมืองหนุ่มนั้นบอกฉันว่าเขาจะช่วยเราผ่านวิกฤตนี้!",
  ui_story_5071_50711401_43_dialog_content = "กำลังเสริมอยู่นอกประตูแต่ยังไม่ได้ทำอะไรเลย ดังนั้นพวกเขากำลังให้เราเคารพมากกว่าปกติ",
  ui_story_5071_50711401_44_dialog_content = "ฉันแค่ต้องไปลงนามในแพกต์ แล้วพวกเขาจะร่วมสู้ด้วยกับอัมบราตันต่อสู้กับกองทัพอิคลิพไซท์!",
  ui_story_5071_50711401_45_dialog_content = "ถ้าคุณแสดงตัวตอนนี้ พวกเขาจะโจมตีคุณเท่านั้น อยู่และคุยกับฉันสักครู่ แล้วฉันจะช่วยคุณวางแผน",
  ui_story_5071_50711401_46_dialog_content = "ไม่ต้องห่วงนะ เราปลอดภัยที่นี่ ไม่มีใครจะได้ยินเราหรอก",
  ui_story_5071_50711401_47_dialog_content = "เงื่อนไขของสนธิสัญญานี้คืออะไร Kade? คุณเตรียมอะไรไว้เพื่อแลกเปลี่ยนกับความช่วยเหลือจากลูโมโพลิสหรือไม่?",
  ui_story_5071_50711401_48_dialog_content = "คนของอัมบราตัน? การค้าเสรี? หรือมันเป็นภาษีที่มากขึ้น? พวกเขาได้ทิ้งอัมบราตันไปแล้วและจะแย่ลงเมื่อพวกเขากลับมา!",
  ui_story_5071_50711401_49_dialog_content = "ทำไมคุณถึงทรยศอัมบราตันเพื่อไปอ้อนวอนลูโมโพลิส? คุณจริง ๆ แล้วยอมแพ้ในความฝันของเราหรือ?",
  ui_story_5071_50711401_50_dialog_content = "ได้รับการอนุมัติจากพ่อของเราเช่นเดียวกับสมาคิดของกิลด์ คทาที่อยู่ในมือฉันและจดหมายที่ลงนามนี้คือหลักฐาน",
  ui_story_5071_50711401_51_dialog_content = "นี่คือการยินยอมอย่างเป็นเอกฉันท์ของพวกเขา",
  ui_story_5071_50711401_52_dialog_content = "คนที่อยู่ในสังคมชั้นล่างของอัมบราตัน คนที่ถูกกดขี่ทั้งโดยลูโมโพลิสและกิลด์ใหญ่ๆ - คุณเคยถามว่าพวกเขารู้สึกอย่างไรเกี่ยวกับสิ่งนี้หรือไม่?",
  ui_story_5071_50711401_53_dialog_content = "ข้อมูลของเราบอกว่าฝูงอิคลิพไซท์จะมาถึงที่นี่ในอีกหนึ่งวัน แต่กองกำลังอิสระของอัมบราตันแต่ละกลุ่มมีวาระของตนเอง",
  ui_story_5071_50711401_54_dialog_content = "แม้กระนั้น พ่อและสมาคมก็เป็นผู้ที่แรกที่เข้ามาช่วยลูโมโพลิสเพื่อความปลอดภัย ในขณะที่ตระกูลแกมบีและพันธมิตรของพวกเขาเริ่มเพิ่มราคาตั๋วขึ้นสำหรับการขนส่งออกจากเมือง...",
